pages.css:
.tickets-intro{padding-bottom:0}
.tickets-card{display:flex;flex-direction:column;gap:0.75rem;position:relative}
.tickets-card-featured{border:2px solid var(--color-primary-dark)}
.tickets-badge{position:absolute;top:-0.9rem;left:1rem;background:var(--color-primary-dark);color:#ffffff;padding:0.25rem 0.75rem;border-radius:999px;font-size:0.8rem;font-weight:700;margin:0}
.tickets-price{font-size:2rem;font-weight:700;color:var(--color-primary-dark);margin:0}
.tickets-features{margin:0;padding-left:1.1rem;flex-grow:1}
.tickets-features li{margin-bottom:0.4rem}
.tickets-card .btn{margin-top:0.5rem}
.tickets-note{font-size:0.9rem;color:var(--color-text);margin-top:1rem}
.tickets-faq-list{display:flex;flex-direction:column;gap:1rem;max-width:45rem}
.tickets-faq-item{border:1px solid var(--color-border);border-radius:var(--radius);padding:1rem}
.tickets-faq-item summary{font-weight:700;cursor:pointer}
.tickets-faq-item p{margin-top:0.75rem;margin-bottom:0}
.tickets-reserve-form{margin-top:1.5rem}
.tickets-reserve-form label{color:var(--color-text-on-dark)}
@media (max-width:600px){
  .tickets-price{font-size:1.6rem}
  .tickets-badge{position:static;display:inline-block;margin-bottom:0.5rem}
}
@media (min-width:601px){
  .tickets-reserve-form{max-width:32rem}
}

